<linearGradient id="rail32f" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#e30513" stop-opacity=".10"/><stop offset="1" stop-color="#0a2885" stop-opacity=".10"/></linearGradient>
